mapper.select:
SELECT id, account_id AS accountId, account_name AS accountName, agent_key AS agentKey, agent_name AS agentName, session_id AS sessionId, request_message AS requestMessage, response_status AS responseStatus, response_content AS responseContent, error_msg AS errorMsg, duration_ms AS durationMs, source, created_at AS createdAt FROM ai_call_log WHERE 1=1
AND account_id = #{accountId}
AND agent_key = #{agentKey}
AND response_status = #{responseStatus}
AND created_at >= #{startDate}
AND created_at < #{endDate}
ORDER BY created_at DESC

SELECT agent_key AS agentKey, agent_name AS agentName, COUNT(*) AS callCount, AVG(duration_ms) AS avgDuration, SUM(CASE WHEN response_status = 'success' THEN 1 ELSE 0 END) AS successCount, SUM(CASE WHEN response_status = 'error' THEN 1 ELSE 0 END) AS errorCount FROM ai_call_log WHERE 1=1
AND account_id = #{accountId}
AND created_at >= #{startDate}
AND created_at < #{endDate}
GROUP BY agent_key, agent_name ORDER BY callCount DESC

SELECT DATE(created_at) AS date, COUNT(*) AS callCount, AVG(duration_ms) AS avgDuration, SUM(CASE WHEN response_status = 'success' THEN 1 ELSE 0 END) AS successCount FROM ai_call_log WHERE 1=1
AND account_id = #{accountId}
AND created_at >= #{startDate}
AND created_at < #{endDate}
GROUP BY DATE(created_at) ORDER BY DATE(created_at) ASC

SELECT COUNT(*) AS totalCount, SUM(CASE WHEN response_status = 'success' THEN 1 ELSE 0 END) AS successCount, SUM(CASE WHEN response_status = 'error' THEN 1 ELSE 0 END) AS errorCount, AVG(duration_ms) AS avgDuration, MAX(duration_ms) AS maxDuration FROM ai_call_log WHERE 1=1
AND account_id = #{accountId}
AND created_at >= #{startDate}
AND created_at < #{endDate}
